"""只读研究数据库命令行工具；输出原始 JSON，便于后续程序使用。"""
import release_runtime
import argparse, json, re, sys, subprocess, urllib.parse
from pathlib import Path
from html.parser import HTMLParser
UA = 'ResearchCatalog/0.1 (personal research; contact via upstream website)'

def fetch(url, body=None):
    args = ['/usr/bin/curl', '--fail', '--silent', '--show-error', '--location', '--max-time', '25', '--user-agent', UA, '--header', 'Accept: application/json']
    if body is not None:
        args += ['--header', 'Content-Type: application/json;charset=UTF-8', '--data-binary', json.dumps(body, ensure_ascii=False)]
        if url.startswith('https://flk.npc.gov.cn/'):
            args += ['--header', 'Referer: https://flk.npc.gov.cn/']
    args += [url]
    result = release_runtime.run(args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if result.returncode:
        from diagnostics import curl_error
        raise curl_error(result.returncode,url,result.stderr)
    return result.stdout.decode('utf-8')

def get(url, params=None, body=None):
    if params:
        url += '?' + urllib.parse.urlencode(params)
    try:
        return json.loads(fetch(url, body))
    except json.JSONDecodeError:
        raise ValueError('上游返回的不是 JSON，可能改版或要求登录')

class Catalog(HTMLParser):

    def __init__(self):
        super().__init__()
        self.items = {}
        self.cur = None

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        href = a.get('href', '')
        m = re.fullmatch('/s/lib/libtb/show/(\\d+)', href)
        if tag == 'a' and m:
            self.cur = (m.group(1), a.get('title', ''))

    def handle_data(self, data):
        if self.cur:
            i, title = self.cur
            name = (title or data).strip()
            if name:
                self.items[i] = {'id': i, 'name': name, 'info_url': 'https://libdb.zju.edu.cn/s/lib/libtb/show/' + i, 'visit_url': 'https://libdb.zju.edu.cn/s/lib/libtb/turning/' + i, 'capability': '目录入口；业务接口未验证'}

    def handle_endtag(self, tag):
        if tag == 'a':
            self.cur = None

class DetailParser(HTMLParser):

    def __init__(self):
        super().__init__()
        self.depth = 0
        self.parts = []
        self.rows = []

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if self.depth:
            self.depth += 1
        elif tag == 'div' and 'onerow' in a.get('class', '').split():
            self.depth = 1
            self.parts = []

    def handle_endtag(self, tag):
        if self.depth:
            self.depth -= 1
            if self.depth == 0:
                self.rows.append(' '.join(''.join(self.parts).split()))

    def handle_data(self, data):
        if self.depth:
            self.parts.append(data)

def library_detail(identifier):
    if not re.fullmatch('\\d+', identifier):
        raise ValueError('数据库编号必须是数字')
    url = 'https://libdb.zju.edu.cn/s/lib/libtb/show/' + identifier
    parser = DetailParser()
    parser.feed(fetch(url))
    fields = {}
    for row in parser.rows:
        for label in ('校内访问方式：', '校外访问方式：', '访问方式：'):
            if row.startswith(label):
                value = row[len(label):]
                fields[label[:-1]] = [x for x in ('IP认证', 'IP登录', '学校IP控制', 'IP控制', 'WebVPN', 'CARSI', 'RVPN', '个人账号') if x.lower() in value.lower() and (not (x == 'IP控制' and '学校IP控制' in value))]
    return {'id': identifier, 'info_url': url, 'visit_url': 'https://libdb.zju.edu.cn/s/lib/libtb/turning/' + identifier, 'declared_access_methods': fields, 'note': '学校页面声明的方式，不代表本机机构身份已验证'}

def catalog():
    html = fetch('https://libdb.zju.edu.cn/s/lib/libtb/')
    p = Catalog()
    p.feed(html)
    return list(p.items.values())

